using System;using System.Reflection;using UnityEngine;
public static class VerifyDepositCache {
public static object Main(){var source=UnityEngine.Object.FindFirstObjectByType<GrainPile>();var p=GrainPile.CreateDroppedPile(new Vector3(20000,1000,20000),source,7.5f);var k=p.GetComponent<CornSurfaceKernels>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;var build=typeof(CornSurfaceKernels).GetMethod("Build",flags);var late=typeof(GrainPile).GetMethod("LateUpdate",flags);var samples=typeof(CornSurfaceKernels).GetField("samples",flags);var initial=samples.GetValue(k);double max=0;try{for(int i=0;i<12;i++){var cargo=new GrainCargo();cargo.Add(GrainType.Corn,.625f);var sw=System.Diagnostics.Stopwatch.StartNew();if(!p.Deposit(p.transform.position,cargo,GrainPile.DropRadius(7.5f)))throw new Exception("Deposit rejected");late.Invoke(p,null);build.Invoke(k,null);max=Math.Max(max,sw.Elapsed.TotalMilliseconds);if(!ReferenceEquals(initial,samples.GetValue(k)))throw new Exception("Deposit rebuilt samples");if(k.LastUpdatedKernels>4096)throw new Exception("Update budget exceeded");}for(int i=0;i<1000&&k.HasPendingSurfaceUpdates;i++)build.Invoke(k,null);if(k.KernelCount==0||k.HasPendingSurfaceUpdates)throw new Exception("Missing grain or stuck queue");return new{passed=true,portions=12,maxDepositAndUpdateMs=max,kernels=k.KernelCount,mass=p.CollectibleKilograms};}finally{UnityEngine.Object.DestroyImmediate(p.gameObject);}}}
